const lead = $json;

const errors = [];


// =========================================
// REQUIRED FIELDS
// =========================================

const requiredFields = [
  'lead_id',
  'first_name',
  'last_name',
  'email',
  'company',
  'website',
  'job_title',
  'city',
  'country',
  'lead_source'
];

for (const field of requiredFields) {
  const value = lead[field];

  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ''
  ) {
    errors.push(`Missing required field: ${field}`);
  }
}


// =========================================
// EMAIL VALIDATION
// =========================================

const normalizedEmail =
  typeof lead.email === 'string'
    ? lead.email.trim().toLowerCase()
    : '';

const emailPattern =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (
  normalizedEmail &&
  !emailPattern.test(normalizedEmail)
) {
  errors.push('Invalid email format');
}


// =========================================
// WEBSITE NORMALIZATION
// =========================================

const normalizedWebsite =
  typeof lead.website === 'string'
    ? lead.website.trim()
    : '';


// =========================================
// PRIVATE IPv4 CHECK
// =========================================

function isPrivateIPv4(hostname) {

  const parts =
    hostname
      .split('.')
      .map(Number);

  if (
    parts.length !== 4 ||
    parts.some(
      part =>
        !Number.isInteger(part) ||
        part < 0 ||
        part > 255
    )
  ) {
    return false;
  }

  const [a, b] = parts;

  // 0.0.0.0/8
  if (a === 0) {
    return true;
  }

  // 10.0.0.0/8
  if (a === 10) {
    return true;
  }

  // 100.64.0.0/10
  if (
    a === 100 &&
    b >= 64 &&
    b <= 127
  ) {
    return true;
  }

  // 127.0.0.0/8
  if (a === 127) {
    return true;
  }

  // 169.254.0.0/16
  if (
    a === 169 &&
    b === 254
  ) {
    return true;
  }

  // 172.16.0.0/12
  if (
    a === 172 &&
    b >= 16 &&
    b <= 31
  ) {
    return true;
  }

  // 192.168.0.0/16
  if (
    a === 192 &&
    b === 168
  ) {
    return true;
  }

  // Multicast / reserved
  if (a >= 224) {
    return true;
  }

  return false;
}


// =========================================
// PRIVATE IPv6 CHECK
// =========================================

function isPrivateIPv6(hostname) {

  const host =
    String(hostname || '')
      .replace(/^\[/, '')
      .replace(/\]$/, '')
      .toLowerCase();

  if (
    host === '::1' ||
    host === '::'
  ) {
    return true;
  }

  // fc00::/7
  if (
    host.startsWith('fc') ||
    host.startsWith('fd')
  ) {
    return true;
  }

  // fe80::/10
  if (
    host.startsWith('fe8') ||
    host.startsWith('fe9') ||
    host.startsWith('fea') ||
    host.startsWith('feb')
  ) {
    return true;
  }

  return false;
}


// =========================================
// WEBSITE SAFETY VALIDATION
// =========================================

if (normalizedWebsite) {

  const protocolMatch =
    normalizedWebsite.match(
      /^(https?):\/\/(.+)$/i
    );

  if (!protocolMatch) {

    errors.push(
      'Website must use HTTP or HTTPS'
    );

  }

  else {

    const remainder =
      protocolMatch[2];

    const authority =
      remainder.split(/[/?#]/)[0];

    // Block embedded credentials
    if (authority.includes('@')) {
      errors.push(
        'Website URL must not contain credentials'
      );
    }

    let hostname = '';
    let port = '';

    // IPv6 address
    if (authority.startsWith('[')) {

      const closingBracket =
        authority.indexOf(']');

      if (closingBracket === -1) {

        errors.push(
          'Invalid website URL'
        );

      }

      else {

        hostname =
          authority
            .slice(
              1,
              closingBracket
            )
            .toLowerCase();

        const afterBracket =
          authority.slice(
            closingBracket + 1
          );

        if (
          afterBracket.startsWith(':')
        ) {
          port =
            afterBracket.slice(1);
        }

      }

    }

    else {

      const cleanAuthority =
        authority.includes('@')
          ? authority.split('@').pop()
          : authority;

      const colonIndex =
        cleanAuthority.lastIndexOf(':');

      if (
        colonIndex > -1 &&
        cleanAuthority.indexOf(':') === colonIndex
      ) {

        hostname =
          cleanAuthority
            .slice(0, colonIndex)
            .toLowerCase();

        port =
          cleanAuthority
            .slice(colonIndex + 1);

      }

      else {

        hostname =
          cleanAuthority
            .toLowerCase();

      }

    }


    // =====================================
    // HOSTNAME CHECK
    // =====================================

    if (!hostname) {

      errors.push(
        'Invalid website URL'
      );

    }

    else {

      // localhost / local domains
      if (
        hostname === 'localhost' ||
        hostname.endsWith('.localhost') ||
        hostname.endsWith('.local')
      ) {

        errors.push(
          'Private or local website URLs are not allowed'
        );

      }

      // Private IPv4
      else if (
        isPrivateIPv4(hostname)
      ) {

        errors.push(
          'Private or local website URLs are not allowed'
        );

      }

      // Private IPv6
      else if (
        hostname.includes(':') &&
        isPrivateIPv6(hostname)
      ) {

        errors.push(
          'Private or local website URLs are not allowed'
        );

      }

    }


    // =====================================
    // PORT CHECK
    // =====================================

    if (
      port &&
      port !== '80' &&
      port !== '443'
    ) {

      errors.push(
        'Website URL uses an unsupported port'
      );

    }

  }

}


// =========================================
// FINAL STATUS
// =========================================

const isValid =
  errors.length === 0;


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...lead,

    email:
      normalizedEmail,

    website:
      normalizedWebsite,

    is_valid:
      isValid,

    validation_status:
      isValid
        ? 'VALID'
        : 'INVALID',

    validation_errors:
      errors
  }
};

const lead = $json;


// =========================================
// RUN MODE
// =========================================

const runMode =
  String(lead.run_mode || 'PRODUCTION')
    .trim()
    .toUpperCase();


// =========================================
// NORMALIZE LEAD ID
// =========================================

const normalizedLeadId =
  String(lead.lead_id || '')
    .trim()
    .toLowerCase();


// =========================================
// NORMALIZE EMAIL
// =========================================

const normalizedEmail =
  String(lead.email || '')
    .trim()
    .toLowerCase();


// =========================================
// NORMALIZE COMPANY
// =========================================

const normalizedCompany =
  String(lead.company || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');


// =========================================
// NORMALIZE WEBSITE
// =========================================

const normalizedWebsite =
  String(lead.website || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/+$/, '');


// =========================================
// BUILD ENVIRONMENT-SAFE DEDUPE KEYS
// =========================================

// Example:
// TEST|web-test-001

const leadIdDedupeKey =
  normalizedLeadId
    ? `${runMode}|${normalizedLeadId}`
    : null;


// Example:
// TEST|james@example.com

const emailDedupeKey =
  normalizedEmail
    ? `${runMode}|${normalizedEmail}`
    : null;


// Example:
// TEST|visayas growth systems|example.org

const companyWebsiteDedupeKey =
  normalizedCompany && normalizedWebsite
    ? `${runMode}|${normalizedCompany}|${normalizedWebsite}`
    : null;


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...lead,

    run_mode: runMode,

    normalized_email:
      normalizedEmail,

    normalized_company:
      normalizedCompany,

    normalized_website:
      normalizedWebsite,

    lead_id_dedupe_key:
      leadIdDedupeKey,

    email_dedupe_key:
      emailDedupeKey,

    company_website_dedupe_key:
      companyWebsiteDedupeKey
  }
};

const lookupResult = $json;

const lead =
  $('Prepare Lead for Deduplication')
    .first()
    .json;


// =========================================
// DUPLICATE FOUND?
// =========================================

const duplicateFound =
  lookupResult.id !== undefined &&
  lookupResult.id !== null;


// =========================================
// DETERMINE MATCH TYPE
// =========================================

let duplicateMatchType = null;

if (duplicateFound) {

  if (
    lookupResult.lead_id_dedupe_key &&
    lookupResult.lead_id_dedupe_key ===
      lead.lead_id_dedupe_key
  ) {
    duplicateMatchType =
      'LEAD_ID';
  }

  else if (
    lookupResult.email_dedupe_key &&
    lookupResult.email_dedupe_key ===
      lead.email_dedupe_key
  ) {
    duplicateMatchType =
      'EMAIL';
  }

  else if (
    lookupResult.company_website_dedupe_key &&
    lookupResult.company_website_dedupe_key ===
      lead.company_website_dedupe_key
  ) {
    duplicateMatchType =
      'COMPANY_WEBSITE';
  }

  else {
    duplicateMatchType =
      'UNKNOWN';
  }

}


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...lead,

    duplicate_found:
      duplicateFound,

    duplicate_status:
      duplicateFound
        ? 'DUPLICATE'
        : 'NEW_LEAD',

    duplicate_match_type:
      duplicateMatchType,

    existing_lead_id:
      duplicateFound
        ? lookupResult.id
        : null
  }
};

const response = $json;


// =========================================
// GET ORIGINAL VALIDATED LEAD
// =========================================

const originalLead =
  $('Prepare Lead for Deduplication')
    .first()
    .json;


// =========================================
// GET CREATED DATABASE RECORD
// =========================================

const databaseLead =
  $('Create New Lead Record')
    .first()
    .json;


// =========================================
// GET HTML
// =========================================

const html =
  String(
    response.website_html || ''
  );


// =========================================
// REMOVE SCRIPT + STYLE CONTENT
// =========================================

let text = html
  .replace(
    /<script\b[^>]*>[\s\S]*?<\/script>/gi,
    ' '
  )
  .replace(
    /<style\b[^>]*>[\s\S]*?<\/style>/gi,
    ' '
  );


// =========================================
// REMOVE HTML TAGS
// =========================================

text = text.replace(
  /<[^>]+>/g,
  ' '
);


// =========================================
// DECODE COMMON HTML ENTITIES
// =========================================

text = text
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');


// =========================================
// NORMALIZE WHITESPACE
// =========================================

text = text
  .replace(/\s+/g, ' ')
  .trim();


// =========================================
// LIMIT WEBSITE TEXT SIZE
// =========================================

const websiteText =
  text.slice(
    0,
    10000
  );


// =========================================
// OUTPUT
// =========================================

return {
  json: {

    // Keep config + validation + dedupe fields
    ...originalLead,

    // Add database-generated fields such as
    // id, created_at, updated_at
    ...databaseLead,

    website_fetch_status:
      'SUCCESS',

    website_text:
      websiteText,

    website_text_length:
      websiteText.length
  }
};

const lead = $json;


// =========================================
// TEST FIXTURE: HIGH-VALUE BUSINESS
// =========================================

const highValueCompanyProfile = `
Visayas Growth Systems is a Cebu City-based business services company.

The company helps small and medium-sized businesses improve their
operations using workflow automation, CRM systems, lead management,
customer support processes, reporting, and administrative automation.

Its services include:
- Workflow automation
- CRM setup and optimization
- Lead management
- Customer support automation
- Business process consulting
- Reporting automation

The company primarily serves local service-based businesses in the
Philippines and works directly with business owners and operations teams.
`;


// =========================================
// TEST FIXTURE: LOW-VALUE BUSINESS
// =========================================

const lowValueCompanyProfile = `
Cebu Hobby Notes is a small personal hobby website maintained by
individual contributors.

The website publishes informal articles about hobbies, personal
interests, watercolor painting, journaling, and creative activities.

It is not operated as a commercial business.

It does not sell products or professional services.

It does not have a sales team, CRM process, appointment system,
customer support department, or business operations team.

The website is mainly used for personal publishing and sharing
non-commercial hobby content.
`;


// =========================================
// TEST FIXTURE: LOW-CONFIDENCE LEAD
// =========================================

const lowConfidenceCompanyProfile = `
Very limited information is available about this organization.

The available page does not clearly explain what the company does,
who it serves, whether it is commercial, or what operational systems
it currently uses.

There is not enough reliable evidence to confidently determine its
industry, business model, or automation needs.
`;


// =========================================
// GENERIC TEST FIXTURE
// =========================================

const genericTestProfile = `
This is a controlled test record.

The available website does not contain reliable real-world company
information.

Use conservative classifications.

If there is not enough evidence to determine business intent or
automation needs, recommend Manual Review and lower the confidence score.
`;


// =========================================
// DETERMINE ENRICHMENT SOURCE
// =========================================

let enrichmentSource;
let companyContext;


// HIGH-VALUE TEST LEADS

if (
  lead.run_mode === 'TEST' &&
  (
    lead.lead_id === 'TEST-002' ||
    lead.lead_id === 'TEST-006'
  )
) {

  enrichmentSource =
    'TEST_FIXTURE_HIGH_VALUE';

  companyContext =
    highValueCompanyProfile.trim();

}


// LOW-VALUE TEST LEADS

else if (
  lead.run_mode === 'TEST' &&
  (
    lead.lead_id === 'TEST-003' ||
    lead.lead_id === 'TEST-007'
  )
) {

  enrichmentSource =
    'TEST_FIXTURE_LOW_VALUE';

  companyContext =
    lowValueCompanyProfile.trim();

}


// LOW-CONFIDENCE TEST LEAD

else if (
  lead.run_mode === 'TEST' &&
  lead.lead_id === 'TEST-004'
) {

  enrichmentSource =
    'TEST_FIXTURE_LOW_CONFIDENCE';

  companyContext =
    lowConfidenceCompanyProfile.trim();

}


// GENERIC TEST DOMAINS

else if (
  lead.run_mode === 'TEST' &&
  (
    lead.normalized_website === 'example.com' ||
    lead.normalized_website === 'example.org' ||
    lead.normalized_website === 'example.net' ||
    lead.normalized_website === 'example.edu'
  )
) {

  enrichmentSource =
    'TEST_FIXTURE_GENERIC';

  companyContext =
    genericTestProfile.trim();

}


// PRODUCTION / REAL WEBSITE

else {

  enrichmentSource =
    'LIVE_WEBSITE';

  companyContext =
    String(
      lead.website_text || ''
    ).trim();

}


// =========================================
// BUILD AI INPUT
// =========================================

const enrichmentContext = `
LEAD INFORMATION

First Name: ${lead.first_name}
Last Name: ${lead.last_name}
Job Title: ${lead.job_title}
Company: ${lead.company}
City: ${lead.city}
Country: ${lead.country}
Website: ${lead.website}

COMPANY INFORMATION

${companyContext}
`.trim();


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...lead,

    enrichment_source:
      enrichmentSource,

    company_context:
      companyContext,

    enrichment_context:
      enrichmentContext
  }
};

const aiResult = $json.output || {};

const lead =
  $('Prepare Enrichment Context')
    .first()
    .json;


// =========================================
// NORMALIZE AI FIELDS
// =========================================

const industry =
  String(
    aiResult.industry || 'Unknown'
  ).trim();


const businessType =
  String(
    aiResult.business_type || 'Unknown'
  ).trim();


const recommendedService =
  String(
    aiResult.recommended_service || 'Manual Review'
  ).trim();


let aiConfidence =
  Number(
    aiResult.ai_confidence
  );


if (
  !Number.isFinite(aiConfidence)
) {
  aiConfidence = 0;
}


aiConfidence =
  Math.max(
    0,
    Math.min(
      1,
      aiConfidence
    )
  );


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...lead,

    industry:
      industry,

    business_type:
      businessType,

    recommended_service:
      recommendedService,

    ai_confidence:
      aiConfidence,

    enrichment_status:
      'AI_ENRICHED'
  }
};

const lead = $json;


// =========================================
// CONFIG
// =========================================

const leadScoreThreshold =
  Number(lead.lead_score_threshold || 70);


// =========================================
// NORMALIZED VALUES
// =========================================

const jobTitle =
  String(lead.job_title || '')
    .trim()
    .toLowerCase();

const industry =
  String(lead.industry || '')
    .trim()
    .toLowerCase();

const businessType =
  String(lead.business_type || '')
    .trim()
    .toLowerCase();

const recommendedService =
  String(lead.recommended_service || '')
    .trim()
    .toLowerCase();

const aiConfidence =
  Number(lead.ai_confidence || 0);


// =========================================
// SCORE 1: VALID LEAD
// MAX: 10
// =========================================

let validLeadScore = 0;

if (lead.is_valid === true) {
  validLeadScore = 10;
}


// =========================================
// SCORE 2: JOB TITLE
// MAX: 20
// =========================================

let jobTitleScore = 0;

const highValueTitles = [
  'owner',
  'founder',
  'ceo',
  'president',
  'director',
  'operations manager',
  'general manager',
  'clinic manager'
];

const mediumValueTitles = [
  'manager',
  'operations',
  'marketing',
  'sales'
];

if (
  highValueTitles.some(
    title => jobTitle.includes(title)
  )
) {
  jobTitleScore = 20;
}

else if (
  mediumValueTitles.some(
    title => jobTitle.includes(title)
  )
) {
  jobTitleScore = 10;
}


// =========================================
// SCORE 3: BUSINESS TYPE
// MAX: 15
// =========================================

let businessTypeScore = 0;

const targetBusinessTypes = [
  'b2b service provider',
  'b2c service provider',
  'local service business',
  'healthcare provider',
  'saas company'
];

if (
  targetBusinessTypes.includes(businessType)
) {
  businessTypeScore = 15;
}


// =========================================
// SCORE 4: INDUSTRY
// MAX: 15
// =========================================

let industryScore = 0;

const targetIndustries = [
  'business services',
  'healthcare',
  'dental',
  'real estate',
  'technology',
  'professional services',
  'e-commerce'
];

if (
  targetIndustries.includes(industry)
) {
  industryScore = 15;
}


// =========================================
// SCORE 5: AUTOMATION OPPORTUNITY
// MAX: 15
// =========================================

let automationOpportunityScore = 0;

if (
  recommendedService &&
  recommendedService !== 'manual review'
) {
  automationOpportunityScore = 15;
}


// =========================================
// SCORE 6: WEBSITE FETCH
// MAX: 10
// =========================================

let websiteScore = 0;

if (
  lead.website_fetch_status === 'SUCCESS'
) {
  websiteScore = 10;
}


// =========================================
// SCORE 7: AI CONFIDENCE
// MAX: 15
// =========================================

let aiConfidenceScore = 0;

if (aiConfidence >= 0.90) {
  aiConfidenceScore = 15;
}

else if (aiConfidence >= 0.75) {
  aiConfidenceScore = 10;
}


// =========================================
// TOTAL SCORE
// =========================================

let leadScore =
  validLeadScore +
  jobTitleScore +
  businessTypeScore +
  industryScore +
  automationOpportunityScore +
  websiteScore +
  aiConfidenceScore;

leadScore =
  Math.min(
    100,
    Math.max(0, leadScore)
  );


// =========================================
// PRIORITY
// =========================================

let priority;

if (leadScore >= 85) {
  priority = 'HIGH';
}

else if (leadScore >= 70) {
  priority = 'MEDIUM';
}

else {
  priority = 'LOW';
}


// =========================================
// QUALIFICATION PREVIEW
// =========================================

const meetsScoreThreshold =
  leadScore >= leadScoreThreshold;


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...lead,

    lead_score: leadScore,

    priority,

    lead_score_threshold:
      leadScoreThreshold,

    meets_score_threshold:
      meetsScoreThreshold,

    scoring_status:
      'SCORED',

    score_breakdown: {
      valid_lead: validLeadScore,
      job_title: jobTitleScore,
      business_type: businessTypeScore,
      industry: industryScore,
      automation_opportunity:
        automationOpportunityScore,
      website_fetch: websiteScore,
      ai_confidence: aiConfidenceScore
    }
  }
};

