const input = $json;


// =========================================
// GET ORIGINAL WEBHOOK DATA
// =========================================

const webhookData =
  $('Lead Intake Webhook')
    .first()
    .json;


// =========================================
// GET WEBHOOK BODY
// =========================================

const body =
  webhookData.body &&
  typeof webhookData.body === 'object'
    ? webhookData.body
    : {};


// =========================================
// DETERMINE RUN MODE
// =========================================

// n8n webhook-test URL:
// executionMode = "test"
//
// Active production webhook:
// executionMode = "production"

const executionMode =
  String(
    webhookData.executionMode || ''
  )
    .trim()
    .toLowerCase();

const runMode =
  executionMode === 'test'
    ? 'TEST'
    : 'PRODUCTION';


// =========================================
// NORMALIZE INCOMING LEAD
// =========================================

const leadId =
  String(body.lead_id || '')
    .trim();

const firstName =
  String(body.first_name || '')
    .trim();

const lastName =
  String(body.last_name || '')
    .trim();

const email =
  String(body.email || '')
    .trim()
    .toLowerCase();

const company =
  String(body.company || '')
    .trim();

const website =
  String(body.website || '')
    .trim();

const jobTitle =
  String(body.job_title || '')
    .trim();

const city =
  String(body.city || '')
    .trim();

const country =
  String(body.country || '')
    .trim();

const leadSource =
  String(
    body.lead_source ||
    input.source ||
    'WEBHOOK'
  ).trim();


// =========================================
// CONFIG VALUES
// =========================================

const leadScoreThreshold =
  Number(
    input.lead_score_threshold || 70
  );

const aiConfidenceThreshold =
  Number(
    input.ai_confidence_threshold || 0.75
  );

const source =
  String(
    input.source ||
    'WEBHOOK'
  ).trim();

const workflowVersion =
  String(
    input.workflow_version ||
    '1.0'
  ).trim();


// =========================================
// OUTPUT STANDARD LEAD FORMAT
// =========================================

return {
  json: {

    run_mode:
      runMode,

    lead_score_threshold:
      leadScoreThreshold,

    ai_confidence_threshold:
      aiConfidenceThreshold,

    source:
      source,

    workflow_version:
      workflowVersion,

    lead_id:
      leadId,

    first_name:
      firstName,

    last_name:
      lastName,

    email:
      email,

    company:
      company,

    website:
      website,

    job_title:
      jobTitle,

    city:
      city,

    country:
      country,

    lead_source:
      leadSource
  }
};

const errorOutput = $json;

const lead =
  $('Prepare Lead for Deduplication')
    .first()
    .json;


// =========================================
// SAFE TEXT CONVERSION
// =========================================

function toText(value) {

  if (
    value === undefined ||
    value === null
  ) {
    return '';
  }

  if (typeof value === 'string') {
    return value.trim();
  }

  try {
    return JSON.stringify(value);
  }

  catch {
    return String(value);
  }

}


// =========================================
// COLLECT ALL TEXT FROM NESTED ERROR DATA
// =========================================

function collectStrings(
  value,
  results = [],
  depth = 0
) {

  if (depth > 10) {
    return results;
  }

  if (
    value === undefined ||
    value === null
  ) {
    return results;
  }

  if (typeof value === 'string') {

    const text =
      value.trim();

    if (text) {
      results.push(text);
    }

    return results;
  }

  if (
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {

    results.push(
      String(value)
    );

    return results;
  }

  if (Array.isArray(value)) {

    for (const item of value) {

      collectStrings(
        item,
        results,
        depth + 1
      );

    }

    return results;
  }

  if (typeof value === 'object') {

    for (
      const [key, item]
      of Object.entries(value)
    ) {

      // Include useful property names too
      results.push(
        `${key}`
      );

      collectStrings(
        item,
        results,
        depth + 1
      );

    }

  }

  return results;
}


// =========================================
// RAW ERROR PAYLOAD
// =========================================

let rawErrorPayload;

try {

  rawErrorPayload =
    JSON.stringify(
      errorOutput,
      null,
      2
    );

}

catch {

  rawErrorPayload =
    String(errorOutput);

}


// Prevent audit logs from becoming enormous

rawErrorPayload =
  rawErrorPayload.slice(
    0,
    6000
  );


// =========================================
// SEARCH ALL NESTED VALUES
// =========================================

const collectedStrings =
  collectStrings(errorOutput);

const combinedErrorText =
  collectedStrings
    .join(' | ')
    .toLowerCase();


// =========================================
// FIND POSTGRES / SUPABASE ERROR CODE
// =========================================

let errorCode = null;

const postgresCodeMatch =
  combinedErrorText.match(
    /\b\d{5}\b/
  );

if (postgresCodeMatch) {

  errorCode =
    postgresCodeMatch[0];

}


// =========================================
// DETECT UNIQUE CONSTRAINT CONFLICT
// =========================================

// PostgreSQL:
// 23505 = unique_violation

const isUniqueConflict =
  errorCode === '23505' ||
  combinedErrorText.includes('23505') ||
  combinedErrorText.includes('duplicate key') ||
  combinedErrorText.includes('unique constraint') ||
  combinedErrorText.includes('violates unique') ||
  combinedErrorText.includes('unique violation');


// =========================================
// FIND BEST HUMAN-READABLE MESSAGE
// =========================================

const preferredPatterns = [
  'invalid input syntax',
  'duplicate key',
  'violates unique',
  'unique constraint',
  'bad request',
  'not-null constraint',
  'foreign key constraint',
  'permission denied',
  'row-level security'
];

let errorMessage = '';

for (const pattern of preferredPatterns) {

  const match =
    collectedStrings.find(
      value =>
        String(value)
          .toLowerCase()
          .includes(pattern)
    );

  if (match) {

    errorMessage =
      String(match);

    break;
  }

}


// Fall back to likely message properties

if (!errorMessage) {

  errorMessage =
    toText(
      errorOutput.error?.message ||
      errorOutput.errorMessage ||
      errorOutput.message ||
      errorOutput.errorDescription ||
      errorOutput.description
    );

}


// Final fallback

if (!errorMessage) {

  errorMessage =
    'Lead creation failed';

}


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...lead,

    lead_create_failed:
      true,

    is_unique_conflict:
      isUniqueConflict,

    error_code:
      errorCode,

    error_message:
      errorMessage,

    failed_node:
      'Create New Lead Record',

    raw_error_payload:
      rawErrorPayload
  }
};

const recoveredLead = $json;

const incomingLead =
  $('Classify Lead Create Error')
    .first()
    .json;


// =========================================
// DID WE RECOVER THE EXISTING ROW?
// =========================================

const recovered =
  recoveredLead.id !== undefined &&
  recoveredLead.id !== null;


// =========================================
// DETERMINE WHICH KEY MATCHED
// =========================================

let duplicateMatchType = null;

if (recovered) {

  if (
    recoveredLead.lead_id_dedupe_key &&
    recoveredLead.lead_id_dedupe_key ===
      incomingLead.lead_id_dedupe_key
  ) {
    duplicateMatchType =
      'LEAD_ID';
  }

  else if (
    recoveredLead.email_dedupe_key &&
    recoveredLead.email_dedupe_key ===
      incomingLead.email_dedupe_key
  ) {
    duplicateMatchType =
      'EMAIL';
  }

  else if (
    recoveredLead.company_website_dedupe_key &&
    recoveredLead.company_website_dedupe_key ===
      incomingLead.company_website_dedupe_key
  ) {
    duplicateMatchType =
      'COMPANY_WEBSITE';
  }

  else {
    duplicateMatchType =
      'UNKNOWN';
  }

}


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    ...incomingLead,

    duplicate_found:
      recovered,

    duplicate_status:
      recovered
        ? 'DUPLICATE'
        : 'RECOVERY_FAILED',

    duplicate_match_type:
      duplicateMatchType,

    existing_lead_id:
      recovered
        ? recoveredLead.id
        : null,

    duplicate_recovery:
      recovered
        ? 'SUCCESS'
        : 'FAILED'
  }
};

